Returns (A_t, A_r, source).
"""
function ideal_1p1d_generated(u, tau, rr, pres, dtp, dtdtp)
    T, ur = u[1], u[2]
    utau = sqrt(1 + ur^2)
    At = SMatrix{2,2}((
        dtp*ur^2 + dtdtp*T*(1 + ur^2),
        (dtp + dtdtp*T)*ur*utau,
        2*dtp*T*ur,
        (dtp*T*(1 + 2*ur^2))/utau))

    Ax = SMatrix{2,2}((
        (dtp + dtdtp*T)*ur*utau,
        dtp + (dtp + dtdtp*T)*ur^2,
        (dtp*T*(1 + 2*ur^2))/utau,
        2*dtp*T*ur))

    source = SVector{2}((
        (dtp*T*(rr + rr*ur^2 + tau*ur*utau))/(rr*tau),
        (dtp*T*ur*(tau*ur + rr*utau))/(rr*tau)))

    return (At, Ax, source)
end

