    T, ur, piphi, pieta, PiB = u[1], u[2], u[3], u[4], u[5]
    utau = sqrt(1 + ur^2)
    At = SMatrix{5,5}((
        dtp*ur^2 + dtdtp*T*(1 + ur^2),
