        (tauS*utau)/rr^2,
        0,
        0,
        -ur^2,
        -(ur*utau),
        0,
        (tauS*utau)/tau^2,
        0,
        ur^2,
        ur*utau,
        0,
        0,
        tauB*utau))

    Ax = SMatrix{5,5}((
        (dtp + dtdtp*T)*ur*utau,
        dtp + (dtp + dtdtp*T)*ur^2,
        0,
        0,
        0,
        ((PiB - pieta - piphi + dtp*T)*(1 + 2*ur^2))/utau,
