        dPP*PiB + zeta,
        -(ur*utau),
        -1 - ur^2,
        (tauS*ur)/rr^2,
        0,
        0,
        -(ur*utau),
        -1 - ur^2,
        0,
        (tauS*ur)/tau^2,
        0,
        ur*utau,
        1 + ur^2,
        0,
        0,
        tauB*ur))

    source = SVector{5}((
        ((PiB + pieta + pres)*rr - rr*(pres + (-PiB + pieta + piphi)*ur^2 - dtp*T*(1 + ur^2)) + (PiB - pieta - piphi + dtp*T)*tau*ur*utau)/(rr*tau),
