        (3*pieta*(dpp*tau*ur + rr*(tau + dpp*utau)) - 2*tau*ur*visc + 4*rr*utau*visc)/(3*rr*tau^3),
        (PiB*rr*tau + dPP*PiB*tau*ur + dPP*PiB*rr*utau + tau*ur*zeta + rr*utau*zeta)/(rr*tau)))

