"""
    two_way_2p1d_generated(u, tau, pres, dtp, dtdtp, zeta, visc, tauS, tauB, dpp, dPP, n, dndT, dnda, h, dhdT, I31, dI31dT, dI31da, aQ, bQ, dbQdT, cQ, dcQdT, Ds, c, wv)

The two-way system: Nabla_mu (T_m + T_Q)^{mu nu} = 0 (fluid rows), the medium pi/Pi rows of S2,
#   the charm rows of S4.  T_Q = (n h - P0) uu + P0 Delta + h (u nu + nu u) + c dM, P0 = n T.

2p1d Cartesian Milne (tau, x, y, eta), u = (u^tau, u^x, u^y, 0).

Fields u = (T, ux, uy, piyy, pieta, pixy, PiB, al, nux, nuy, pQxx, pQxy, pQyy, PiQ).
Returns (A_t, A_x, A_y, source).
"""
function two_way_2p1d_generated(u, tau, pres, dtp, dtdtp, zeta, visc, tauS, tauB, dpp, dPP, n, dndT, dnda, h, dhdT, I31, dI31dT, dI31da, aQ, bQ, dbQdT, cQ, dcQdT, Ds, c, wv)
    T, ux, uy, piyy, pieta, pixy, PiB, al, nux, nuy, pQxx, pQxy, pQyy, PiQ = u[1], u[2], u[3], u[4], u[5], u[6], u[7], u[8], u[9], u[10], u[11], u[12], u[13], u[14]
    utau = sqrt(1 + ux^2 + uy^2)
    At = SMatrix{14,14}((
        -n - dndT*T + dtdtp*T + 2*dhdT*nux*ux + dtp*ux^2 + dtdtp*T*ux^2 + 2*dhdT*nuy*uy + dtp*uy^2 + dtdtp*T*uy^2 + dndT*h*(1 + ux^2 + uy^2) + dhdT*n*(1 + ux^2 + uy^2),
        ((dtp + dndT*h + dtdtp*T)*ux*(1 + ux^2 + uy^2) + dhdT*(nuy*ux*uy + n*ux*(1 + ux^2 + uy^2) + nux*(1 + 2*ux^2 + uy^2)))/utau,
        ((dtp + dndT*h + dtdtp*T)*uy*(1 + ux^2 + uy^2) + dhdT*(nux*ux*uy + n*uy*(1 + ux^2 + uy^2) + nuy*(1 + ux^2 + 2*uy^2)))/utau,
        0,
        0,
        0,
        0,
        dndT*utau,
        (Ds*utau*(dhdT*nux + (n + dndT*T)*ux))/T,
        (Ds*utau*(dhdT*nuy + (n + dndT*T)*uy))/T,
        (Ds*(-2*dbQdT*nuy*(1 + ux^2)*uy + 3*dcQdT*pQxx*(1 + ux^2 + uy^2) + 2*dbQdT*nux*ux*(2 + 2*ux^2 + 3*uy^2)))/(6*T*utau),
        (Ds*(3*dcQdT*pQxy*(1 + ux^2 + uy^2) + dbQdT*nuy*ux*(3 + 3*ux^2 + uy^2) + dbQdT*nux*uy*(3 + ux^2 + 3*uy^2)))/(6*T*utau),
        (Ds*(-2*dbQdT*nux*ux*(1 + uy^2) + 3*dcQdT*pQyy*(1 + ux^2 + uy^2) + 2*dbQdT*nuy*uy*(2 + 3*ux^2 + 2*uy^2)))/(6*T*utau),
        (Ds*(5*dbQdT*(nux*ux + nuy*uy) + 3*dI31dT*(1 + ux^2 + uy^2) + 3*dcQdT*PiQ*(1 + ux^2 + uy^2)))/(6*T*utau),
        (2*(-(pieta*ux) + c*PiQ*ux - piyy*ux + c*pQxx*ux + dtp*T*ux - 2*pieta*ux^3 + 2*c*PiQ*ux^3 - 2*piyy*ux^3 + 2*dtp*T*ux^3 - pieta*ux^5 + c*PiQ*ux^5 - piyy*ux^5 + dtp*T*ux^5 + pixy*uy + c*pQxy*uy + 2*pixy*ux^2*uy - c*pQxy*ux^2*uy + pixy*ux^4*uy - 2*pieta*ux*uy^2 + 3*c*PiQ*ux*uy^2 - 2*piyy*ux*uy^2 + 2*c*pQxx*ux*uy^2 - c*pQyy*ux*uy^2 + 3*dtp*T*ux*uy^2 - 2*pieta*ux^3*uy^2 + 4*c*PiQ*ux^3*uy^2 - 2*piyy*ux^3*uy^2 + 4*dtp*T*ux^3*uy^2 + c*PiQ*ux^5*uy^2 + dtp*T*ux^5*uy^2 + 2*pixy*uy^3 + 2*c*pQxy*uy^3 + 2*pixy*ux^2*uy^3 - c*pQxy*ux^2*uy^3 - pieta*ux*uy^4 + 3*c*PiQ*ux*uy^4 - piyy*ux*uy^4 + c*pQxx*ux*uy^4 - c*pQyy*ux*uy^4 + 3*dtp*T*ux*uy^4 + 2*c*PiQ*ux^3*uy^4 + 2*dtp*T*ux^3*uy^4 + pixy*uy^5 + c*pQxy*uy^5 + c*PiQ*ux*uy^6 + dtp*T*ux*uy^6 + PiB*utau^4*ux*(1 + uy^2) + h*utau^4*(nux + n*ux)*(1 + uy^2)))/(utau^4*(1 + uy^2)),
        (-pieta + c*PiQ - piyy + c*pQxx + dtp*T - 3*pieta*ux^2 + 3*c*PiQ*ux^2 - 3*piyy*ux^2 + 3*dtp*T*ux^2 - 2*pieta*ux^4 + 2*c*PiQ*ux^4 - 2*piyy*ux^4 + 2*dtp*T*ux^4 + 3*pixy*ux*uy - c*pQxy*ux*uy + 2*pixy*ux^3*uy - 2*pieta*uy^2 + 3*c*PiQ*uy^2 - piyy*uy^2 + 2*c*pQxx*uy^2 + 3*dtp*T*uy^2 - 3*pieta*ux^2*uy^2 + 6*c*PiQ*ux^2*uy^2 - 3*piyy*ux^2*uy^2 + 6*dtp*T*ux^2*uy^2 + 2*c*PiQ*ux^4*uy^2 + 2*dtp*T*ux^4*uy^2 + 3*pixy*ux*uy^3 - c*pQxy*ux*uy^3 - pieta*uy^4 + 3*c*PiQ*uy^4 + c*pQxx*uy^4 + 3*dtp*T*uy^4 + 3*c*PiQ*ux^2*uy^4 + 3*dtp*T*ux^2*uy^4 + c*PiQ*uy^6 + dtp*T*uy^6 + PiB*(1 + uy^2)*(2*ux^4 + 3*ux^2*(1 + uy^2) + (1 + uy^2)^2) + h*(1 + uy^2)*(nuy*uy*(1 + uy^2) + nux*ux*(3 + 2*ux^2 + 3*uy^2) + n*(2*ux^4 + 3*ux^2*(1 + uy^2) + (1 + uy^2)^2)))/(utau^3*(1 + uy^2)),
        (h*nuy*ux + h*nuy*ux^3 + h*nux*uy + h*n*ux*uy + PiB*ux*uy - piyy*ux*uy + dtp*T*ux*uy + h*n*ux^3*uy + PiB*ux^3*uy + dtp*T*ux^3*uy + h*nux*uy^3 + h*n*ux*uy^3 + PiB*ux*uy^3 + dtp*T*ux*uy^3 + pixy*(1 + uy^2) + c*pQxy*(1 + uy^2) + c*ux*uy*(-pQyy + PiQ*(1 + ux^2 + uy^2)))/utau^3,
        (3*dpp*piyy*ux - 6*pixy*tauS*uy*(1 + uy^2) - 2*ux*(-3*piyy*tauS*uy^2 + visc + uy^2*visc))/(3*utau),
        (ux*(3*dpp*pieta - 2*visc))/(3*tau^2*utau),
        (3*dpp*pixy*ux - 3*pixy*tauS*ux*(1 + 2*uy^2) + uy*(3*piyy*(tauS + 2*tauS*ux^2) + 3*pieta*tauS*(1 + ux^2 + uy^2) + (3 + ux^2 + 3*uy^2)*visc))/(3*utau),
        (ux*(dPP*PiB + zeta))/utau,
        (-(nuy*ux*uy) + nux*(1 + uy^2) + n*ux*(1 + ux^2 + uy^2))/utau^3,
