        ((dndT*h + 16*aSB*T^3)*uy*(1 + ux^2 + uy^2) + dhdT*(nux*ux*uy + n*uy*(1 + ux^2 + uy^2) + nuy*(1 + ux^2 + 2*uy^2)))/utau,
        0,
        0,
        0,
        dndT*utau,
        (Ds*utau*(dhdT*nux + (n + dndT*T)*ux))/T,
        (Ds*utau*(dhdT*nuy + (n + dndT*T)*uy))/T,
        (Ds*(-2*dbQdT*nuy*(1 + ux^2)*uy + 3*dcQdT*pQxx*(1 + ux^2 + uy^2) + 2*dbQdT*nux*ux*(2 + 2*ux^2 + 3*uy^2)))/(6*T*utau),
        (Ds*(3*dcQdT*pQxy*(1 + ux^2 + uy^2) + dbQdT*nuy*ux*(3 + 3*ux^2 + uy^2) + dbQdT*nux*uy*(3 + ux^2 + 3*uy^2)))/(6*T*utau),
        (Ds*(-2*dbQdT*nux*ux*(1 + uy^2) + 3*dcQdT*pQyy*(1 + ux^2 + uy^2) + 2*dbQdT*nuy*uy*(2 + 3*ux^2 + 2*uy^2)))/(6*T*utau),
        (Ds*(5*dbQdT*(nux*ux + nuy*uy) + 3*dI31dT*(1 + ux^2 + uy^2) + 3*dcQdT*PiQ*(1 + ux^2 + uy^2)))/(6*T*utau),
        (2*(c*PiQ*ux - piyy*ux + c*pQxx*ux + 4*aSB*T^4*ux - pieta*utau^4*ux + 2*c*PiQ*ux^3 - 2*piyy*ux^3 + 8*aSB*T^4*ux^3 + c*PiQ*ux^5 - piyy*ux^5 + 4*aSB*T^4*ux^5 + pixy*uy + c*pQxy*uy + 2*pixy*ux^2*uy - c*pQxy*ux^2*uy + pixy*ux^4*uy + 3*c*PiQ*ux*uy^2 - 2*piyy*ux*uy^2 + 2*c*pQxx*ux*uy^2 - c*pQyy*ux*uy^2 + 12*aSB*T^4*ux*uy^2 + 4*c*PiQ*ux^3*uy^2 - 2*piyy*ux^3*uy^2 + 16*aSB*T^4*ux^3*uy^2 + c*PiQ*ux^5*uy^2 + 4*aSB*T^4*ux^5*uy^2 + 2*pixy*uy^3 + 2*c*pQxy*uy^3 + 2*pixy*ux^2*uy^3 - c*pQxy*ux^2*uy^3 + 3*c*PiQ*ux*uy^4 - piyy*ux*uy^4 + c*pQxx*ux*uy^4 - c*pQyy*ux*uy^4 + 12*aSB*T^4*ux*uy^4 + 2*c*PiQ*ux^3*uy^4 + 8*aSB*T^4*ux^3*uy^4 + pixy*uy^5 + c*pQxy*uy^5 + c*PiQ*ux*uy^6 + 4*aSB*T^4*ux*uy^6 + h*utau^4*(nux + n*ux)*(1 + uy^2)))/(utau^4*(1 + uy^2)),
        (c*PiQ - piyy + c*pQxx + 4*aSB*T^4 + 3*c*PiQ*ux^2 - 3*piyy*ux^2 + 12*aSB*T^4*ux^2 + 2*c*PiQ*ux^4 - 2*piyy*ux^4 + 8*aSB*T^4*ux^4 + 3*pixy*ux*uy - c*pQxy*ux*uy + 2*pixy*ux^3*uy + 3*c*PiQ*uy^2 - piyy*uy^2 + 2*c*pQxx*uy^2 + 12*aSB*T^4*uy^2 + 6*c*PiQ*ux^2*uy^2 - 3*piyy*ux^2*uy^2 + 24*aSB*T^4*ux^2*uy^2 + 2*c*PiQ*ux^4*uy^2 + 8*aSB*T^4*ux^4*uy^2 + 3*pixy*ux*uy^3 - c*pQxy*ux*uy^3 + 3*c*PiQ*uy^4 + c*pQxx*uy^4 + 12*aSB*T^4*uy^4 + 3*c*PiQ*ux^2*uy^4 + 12*aSB*T^4*ux^2*uy^4 + c*PiQ*uy^6 + 4*aSB*T^4*uy^6 - pieta*(2*ux^4 + 3*ux^2*(1 + uy^2) + (1 + uy^2)^2) + h*(1 + uy^2)*(nuy*uy*(1 + uy^2) + nux*ux*(3 + 2*ux^2 + 3*uy^2) + n*(2*ux^4 + 3*ux^2*(1 + uy^2) + (1 + uy^2)^2)))/(utau^3*(1 + uy^2)),
        (h*nuy*ux + h*nuy*ux^3 + h*nux*uy + h*n*ux*uy - piyy*ux*uy + 4*aSB*T^4*ux*uy + h*n*ux^3*uy + 4*aSB*T^4*ux^3*uy + h*nux*uy^3 + h*n*ux*uy^3 + 4*aSB*T^4*ux*uy^3 + pixy*(1 + uy^2) + c*pQxy*(1 + uy^2) + c*ux*uy*(-pQyy + PiQ*(1 + ux^2 + uy^2)))/utau^3,
        (3*dpp*piyy*ux - 6*pixy*tauS*uy*(1 + uy^2) - 2*ux*(-3*piyy*tauS*uy^2 + visc + uy^2*visc))/(3*utau),
