        (Ds*(h*(nuy*ux - nux*uy)*(1 + uy^2)*(1 + ux^2 + uy^2) - c*ux*uy*(pQxx + pQyy + pQxx*uy^2 - pQyy*uy^2) + c*pQxy*(1 + ux^2*uy^2 - uy^4)))/(T*utau^3),
        (Ds*(4*I31*ux + 4*cQ*PiQ*ux + cQ*pQxx*ux + 8*I31*ux^3 + 8*cQ*PiQ*ux^3 + cQ*pQxx*ux^3 + 4*I31*ux^5 + 4*cQ*PiQ*ux^5 + cQ*pQxy*uy + 6*cQ*pQxy*ux^2*uy + 5*cQ*pQxy*ux^4*uy + 10*I31*ux*uy^2 + 10*cQ*PiQ*ux*uy^2 - 2*cQ*pQxx*ux*uy^2 + 2*cQ*pQyy*ux*uy^2 + 10*I31*ux^3*uy^2 + 10*cQ*PiQ*ux^3*uy^2 - 5*cQ*pQxx*ux^3*uy^2 + 2*cQ*pQyy*ux^3*uy^2 + cQ*pQxy*uy^3 + cQ*pQxy*ux^2*uy^3 + 6*I31*ux*uy^4 + 6*cQ*PiQ*ux*uy^4 - 3*cQ*pQxx*ux*uy^4 + 2*aQ*(1 + ux^2 + uy^2)*(nuy*ux*(1 + ux^2)*uy - nux*ux^2*(-2 + uy^2) + 2*nux*(1 + uy^2)) + 2*bQ*nuy*ux*uy*(1 + 3*ux^4 + ux^2*(4 + 3*uy^2)) + bQ*nux*(4 + 10*uy^2 - 6*ux^4*uy^2 + 6*uy^4 - 2*ux^2*(-2 + uy^2 + 3*uy^4)) + 3*cQ*pQxy*uy*wv + 6*cQ*pQxy*ux^2*uy*wv + 3*cQ*pQxy*ux^4*uy*wv - 3*cQ*pQxx*ux*uy^2*wv - 3*cQ*pQxx*ux^3*uy^2*wv + 3*cQ*pQxy*uy^3*wv + 3*cQ*pQxy*ux^2*uy^3*wv - 3*cQ*pQxx*ux*uy^4*wv))/(6*T*utau^3),
        (Ds*(6*cQ*pQxy*ux + 6*cQ*pQxy*ux^3 + 6*I31*uy + 6*cQ*PiQ*uy - 3*cQ*pQxx*uy + 3*cQ*pQyy*uy + 8*I31*ux^2*uy + 8*cQ*PiQ*ux^2*uy - 7*cQ*pQxx*ux^2*uy + 6*cQ*pQyy*ux^2*uy + 2*I31*ux^4*uy + 2*cQ*PiQ*ux^4*uy + 3*cQ*pQyy*ux^4*uy + 2*cQ*pQxy*ux*uy^2 + 4*cQ*pQxy*ux^3*uy^2 + 12*I31*uy^3 + 12*cQ*PiQ*uy^3 - 6*cQ*pQxx*uy^3 + 3*cQ*pQyy*uy^3 + 8*I31*ux^2*uy^3 + 8*cQ*PiQ*ux^2*uy^3 - 7*cQ*pQxx*ux^2*uy^3 + 7*cQ*pQyy*ux^2*uy^3 - 4*cQ*pQxy*ux*uy^4 + 6*I31*uy^5 + 6*cQ*PiQ*uy^5 - 3*cQ*pQxx*uy^5 - 4*bQ*nux*ux*uy*(1 + uy^2)*(4 + 3*ux^2 + 3*uy^2) + 2*aQ*(1 + ux^2 + uy^2)*(3*nuy*(1 + uy^2) - 2*nux*ux*uy*(1 + uy^2) + nuy*ux^2*(3 + 2*uy^2)) + 2*bQ*nuy*(3*(1 + uy^2)^2 + ux^4*(3 + 6*uy^2) + 2*ux^2*(3 + 7*uy^2 + 3*uy^4)) - 3*cQ*pQxx*uy*wv + 3*cQ*pQyy*uy*wv - 3*cQ*pQxx*ux^2*uy*wv + 6*cQ*pQyy*ux^2*uy*wv + 3*cQ*pQyy*ux^4*uy*wv - 6*cQ*pQxx*uy^3*wv + 3*cQ*pQyy*uy^3*wv - 3*cQ*pQxx*ux^2*uy^3*wv + 3*cQ*pQyy*ux^2*uy^3*wv - 3*cQ*pQxx*uy^5*wv))/(12*T*utau^3),
