        dhdT*nuy*ux + (dndT*h + 16*aSB*T^3)*ux*uy + dhdT*(nux + n*ux)*uy,
        n + dndT*T + 4*aSB*T^3 + 2*dhdT*nuy*uy + dndT*h*uy^2 + dhdT*n*uy^2 + 16*aSB*T^3*uy^2,
        0,
