        (Ds*(dhdT*nuy*uy + n*(1 + uy^2) + dndT*T*(1 + uy^2)))/T,
        (Ds*(3*dcQdT*pQxx*uy - 2*dbQdT*(nuy + nuy*ux^2 - 3*nux*ux*uy)))/(6*T),
        (Ds*(3*dcQdT*pQxy*uy + dbQdT*nuy*ux*uy + 3*dbQdT*nux*(1 + uy^2)))/(6*T),
