        (Ds*(5*dbQdT*nuy + 3*(dI31dT + dcQdT*PiQ)*uy))/(6*T),
        (h*nuy*ux + h*nuy*ux^3 + h*nux*uy + h*n*ux*uy - piyy*ux*uy + 4*aSB*T^4*ux*uy + h*n*ux^3*uy + 4*aSB*T^4*ux^3*uy + h*nux*uy^3 + h*n*ux*uy^3 + 4*aSB*T^4*ux*uy^3 + pixy*(1 + uy^2) + c*pQxy*(1 + uy^2) + c*ux*uy*(-pQyy + PiQ*(1 + ux^2 + uy^2)))/utau^3,
        h*nuy + h*n*uy + c*PiQ*uy + 4*aSB*T^4*uy,
        0,
        (-2*tauS*uy^2*(pixy - piyy*ux*uy + pixy*uy^2))/utau^2,
        0,
        (piyy*tauS*uy^2 + 2*piyy*tauS*ux^2*uy^2 + pieta*tauS*uy^2*(1 + ux^2 + uy^2) - pixy*tauS*ux*uy*(1 + 2*uy^2) + visc + ux^2*visc + 2*uy^2*visc + ux^2*uy^2*visc + uy^4*visc)/utau^2,
        0,
        (Ds*(h*(nuy*(1 + ux^2)*(1 + uy^2) - nux*ux*uy*(1 + uy^2) + n*uy*(1 + ux^2 + uy^2)) + c*(pQyy*ux^2*uy - pQxy*ux*(1 + uy^2) + PiQ*uy*(1 + ux^2 + uy^2))))/(T*utau^2),
        -((Ds*uy*(h*uy*(nux - nuy*ux*uy + nux*uy^2) + c*(pQxy - pQyy*ux*uy + pQxy*uy^2)))/(T*utau^2)),
        (Ds*(2*uy*(aQ*nuy*ux*(1 + ux^2)*uy - aQ*nux*ux^2*(-2 + uy^2) + 2*aQ*nux*(1 + uy^2) + 3*I31*ux*(1 + ux^2 + uy^2) + 3*bQ*(nux + nuy*ux^3*uy - nux*(-1 + ux^2)*uy^2)) + cQ*(pQxy*(1 + ux^2)*(1 + uy^2)*(1 + 3*wv) + ux*uy*(2*pQyy*(1 + ux^2) + 6*PiQ*(1 + ux^2 + uy^2) - 3*pQxx*(1 + uy^2)*(1 + wv)))))/(6*T*utau^2),
        (Ds*(6*I31*(1 + uy^2)*(1 + ux^2 + uy^2) + 2*aQ*uy*(3*nuy*(1 + uy^2) - 2*nux*ux*uy*(1 + uy^2) + nuy*ux^2*(3 + 2*uy^2)) - 6*bQ*(1 + uy^2)*(-(nuy*(1 + 2*ux^2)*uy) + nux*(ux + 2*ux*uy^2)) + cQ*(3*pQyy + 3*pQyy*ux^2 - 10*pQxy*ux*uy + 3*pQyy*uy^2 + 7*pQyy*ux^2*uy^2 - 4*pQxy*ux*uy^3 + 6*PiQ*(1 + uy^2)*(1 + ux^2 + uy^2) + 3*pQyy*wv + 3*pQyy*ux^2*wv + 3*pQyy*uy^2*wv + 3*pQyy*ux^2*uy^2*wv - 3*pQxx*(1 + uy^2)*(-1 + wv + uy^2*(1 + wv)))))/(12*T*utau^2),
        -1/6*(Ds*(2*(aQ + 3*bQ)*uy*(1 + uy^2)*(nux - nuy*ux*uy + nux*uy^2) + cQ*(pQxy - pQyy*ux*uy + pQxy*uy^2)*(-1 + 3*wv + uy^2*(5 + 3*wv))))/(T*utau^2),
        (Ds*(aQ*uy*(nux - nuy*ux*uy + nux*uy^2) + cQ*(pQxy - pQyy*ux*uy + pQxy*uy^2)))/(3*T*utau^2),
        (piyy + 4*aSB*T^4 + piyy*ux^2 + 8*aSB*T^4*ux^2 + 4*aSB*T^4*ux^4 - pixy*ux*uy + 12*aSB*T^4*uy^2 + 12*aSB*T^4*ux^2*uy^2 + 8*aSB*T^4*uy^4 + h*(nux*(ux + ux^3) + nuy*uy*(3 + 3*ux^2 + 2*uy^2) + n*(1 + ux^4 + 3*uy^2 + 2*uy^4 + ux^2*(2 + 3*uy^2))) + c*(pQyy + pQyy*ux^2 - pQxy*ux*uy + PiQ*(1 + ux^4 + 3*uy^2 + 2*uy^4 + ux^2*(2 + 3*uy^2))))/utau^3,
        h*nux + h*n*ux + c*PiQ*ux + 4*aSB*T^4*ux,
