        (-6*piyy*tauS*(1 + ux^2)*uy^2 + 6*pixy*tauS*ux*uy^3 + 3*dpp*piyy*(1 + ux^2 + uy^2) + 4*visc + 4*ux^2*visc + 8*uy^2*visc + 4*ux^2*uy^2*visc + 4*uy^4*visc)/(3*utau^2),
        (3*dpp*pieta - 2*visc)/(3*tau^2),
        dpp*pixy - (uy*(3*piyy*tauS*ux*(1 + ux^2)*(1 + 2*uy^2) + 3*pixy*tauS*uy*(1 + (1 - 2*ux^2)*uy^2) + ux*(1 + ux^2 + uy^2)*(3*pieta*tauS*uy^2 - (1 + uy^2)*visc)))/(3*utau^2*(1 + uy^2)),
        n,
        (Ds*(-(c*ux*(pQyy + pQyy*ux^2 - pQxy*ux*uy)) + h*(1 + ux^2)*(nux - nuy*ux*uy + nux*uy^2)))/(T*utau^2),
        (Ds*(c*uy*(-(pQyy*(1 + ux^2)) + pQxy*ux*uy + PiQ*(1 + ux^2 + uy^2)) + h*(nux*ux*uy^3 + n*uy*(1 + ux^2 + uy^2) + nuy*(2 + uy^2 - ux^2*(-2 + uy^2)))))/(T*utau^2),
        -1/6*(Ds*(2*(aQ + aQ*ux^2 + 3*bQ*ux^2)*uy*(nuy + nuy*ux^2 - nux*ux*uy) + 2*I31*(1 + ux^2)*(1 + ux^2 + uy^2) + cQ*(2*PiQ*(1 + ux^2)*(1 + ux^2 + uy^2) + (1 + ux^2)*(2*pQyy*(1 + ux^2) + pQxy*ux*uy*(1 + 3*wv)) - 3*pQxx*(1 + uy^2 + ux^2*(1 + uy^2*(1 + wv))))))/(T*utau^2),
        (Ds*(6*bQ*nux*(1 + 2*ux^2)*uy*(1 + uy^2) + 6*cQ*pQxy*(2 + uy^2) + 4*cQ*pQxy*ux^2*(3 + uy^2) + 2*I31*ux*uy*(1 + ux^2 + uy^2) - 6*bQ*nuy*ux*(1 + ux^2)*(1 + 2*uy^2) + 2*aQ*uy*(-2*nuy*ux*(1 + ux^2)*uy + 3*nux*(1 + uy^2) + nux*ux^2*(3 + 2*uy^2)) + cQ*ux*uy*(2*PiQ*(1 + ux^2 + uy^2) - pQyy*(1 + ux^2)*(7 + 3*wv) + 3*pQxx*(-1 + wv + uy^2*(1 + wv)))))/(12*T*utau^2),
        (Ds*(4*I31*(1 + uy^2)*(1 + ux^2 + uy^2) + 2*uy*(3*bQ*ux*uy*(nux - nuy*ux*uy + nux*uy^2) + aQ*(-(nuy*ux^2*(-2 + uy^2)) + 2*nuy*(1 + uy^2) + nux*ux*uy*(1 + uy^2))) + cQ*(4*PiQ*(1 + uy^2)*(1 + ux^2 + uy^2) + pQxy*ux*uy*(-1 + 3*wv + uy^2*(5 + 3*wv)) + pQyy*(7 + uy^2 + ux^2*(7 - uy^2*(5 + 3*wv))))))/(6*T*utau^2),
        (Ds*(2*aQ*uy*(nuy + nuy*ux^2 - nux*ux*uy) + 2*cQ*(pQyy + pQyy*ux^2 - pQxy*ux*uy) + 5*I31*(1 + ux^2 + uy^2) + 5*cQ*PiQ*(1 + ux^2 + uy^2)))/(6*T*utau^2),
        uy/utau,
