    source = SVector{13}((
        (h*(2*(nux*ux + nuy*uy) + n*(1 + ux^2 + uy^2)) + (c*(1 + uy^2)*(-pQyy + PiQ*utau^4 - pQyy*ux^2 + 4*pQxy*ux*uy + pQyy*uy^2 + pQxx*(-1 + ux^2 - uy^2)) + pieta*(-ux^4 + (1 + uy^2)^2) + (1 + ux^2 + uy^2)*(2*pixy*ux*uy + piyy*(-ux^2 + uy^2) + 4*aSB*T^4*(1 + uy^2)*(1 + ux^2 + uy^2)))/(utau^2*(1 + uy^2)))/tau,
        (pixy*uy*(1 + uy^2) + n*(h - T)*ux*(1 + uy^2)*(1 + ux^2 + uy^2) + n*T*ux*(1 + uy^2)*(1 + ux^2 + uy^2) + 4*aSB*T^4*ux*(1 + uy^2)*(1 + ux^2 + uy^2) - ux*(piyy + piyy*ux^2 - 2*pixy*ux*uy + pieta*(1 + ux^2 + uy^2)) + c*(1 + uy^2)*(pQxx*ux + pQxy*uy + PiQ*ux*(1 + ux^2 + uy^2)) + h*(1 + uy^2)*(nuy*ux*uy + nux*(1 + 2*ux^2 + uy^2)))/(tau*utau*(1 + uy^2)),
        (pixy*ux + c*pQxy*ux + c*PiQ*uy + piyy*uy + c*pQyy*uy + 4*aSB*T^4*uy + c*PiQ*ux^2*uy + 4*aSB*T^4*ux^2*uy + c*PiQ*uy^3 + 4*aSB*T^4*uy^3 + h*(nux*ux*uy + n*uy*(1 + ux^2 + uy^2) + nuy*(1 + ux^2 + 2*uy^2)))/(tau*utau),
        piyy + (dpp*piyy*utau)/tau - (2*utau*(1 + uy^2)*visc)/(3*tau),
        (3*pieta*(tau + dpp*utau) + 4*utau*visc)/(3*tau^3),
        pixy + (dpp*pixy*utau)/tau - (2*utau*ux*uy*visc)/(3*tau),
        (nux*ux + nuy*uy + n*(1 + ux^2 + uy^2))/(tau*utau),
        nux + (Ds*h*nux*utau)/(T*tau) + (c*Ds*(pQyy*(ux + ux^3) + pQxy*(1 - 2*ux^2)*uy + pQxx*ux*(2 + uy^2)))/(T*tau*utau),
        nuy + (Ds*(h*nuy*(1 + ux^2 + uy^2) + c*pQxy*(ux - 2*ux*uy^2) + c*uy*(pQyy*(2 + ux^2) + pQxx*(1 + uy^2))))/(T*tau*utau),
        pQxx - (Ds*(2*bQ*(1 + ux^2)*(nux*ux + nuy*uy) + 2*I31*(1 + ux^2)*(1 + ux^2 + uy^2) + cQ*(-2*(1 + ux^2)*(pQyy + pQyy*ux^2 - 2*pQxy*ux*uy) + 2*PiQ*(1 + ux^2)*(1 + ux^2 + uy^2) - pQxx*(5*(1 + uy^2) + ux^2*(5 + 2*uy^2)))))/(6*T*tau*utau),
        (6*pQxy*T*tau*utau - 2*Ds*ux*uy*(I31 + bQ*nux*ux + I31*ux^2 + bQ*nuy*uy + I31*uy^2) + cQ*Ds*(pQxy*(ux^2*(3 - 4*uy^2) + 3*(1 + uy^2)) + 2*ux*uy*(pQxx + pQyy + pQyy*ux^2 + pQxx*uy^2 - PiQ*(1 + ux^2 + uy^2))))/(6*T*tau*utau),
        pQyy - (Ds*(2*bQ*(nux*ux + nuy*uy)*(1 + uy^2) + 2*I31*(1 + uy^2)*(1 + ux^2 + uy^2) + cQ*(-5*pQyy - 5*pQyy*ux^2 + 4*pQxy*ux*uy - 5*pQyy*uy^2 - 2*pQyy*ux^2*uy^2 + 4*pQxy*ux*uy^3 - 2*pQxx*(1 + uy^2)^2 + 2*PiQ*(1 + uy^2)*(1 + ux^2 + uy^2))))/(6*T*tau*utau),
        PiQ + (Ds*(5*bQ*(nux*ux + nuy*uy) + 5*I31*(1 + ux^2 + uy^2) + 5*cQ*PiQ*(1 + ux^2 + uy^2) - 2*cQ*(pQxx + pQyy + pQyy*ux^2 - 2*pQxy*ux*uy + pQxx*uy^2)))/(6*T*tau*utau)))

    return (At, Ax, Ay, source)
end
